/**
 * Pchat — about page renderer
 * =====================================================================
 * Fills the live numbers on the About page from `window.HelpData`
 * (generated by tools/generate-help.js), so the page never claims a
 * number the app does not actually have.
 */
(function () {
  'use strict';

  function esc(s) {
    return String(s == null ? '' : s).replace(/[&<>"']/g, (m) => ({
      '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;',
    }[m]));
  }

  function fill() {
    const D = window.HelpData;
    if (!D) return;

    const stats = [
      [D.assets.emoji.total, 'custom emoji'],
      [D.assets.emoji.categories.length, 'emoji categories'],
      [D.assets.themes, 'wallpapers'],
      [D.assets.music, 'radio tracks'],
      [D.assets.special.count, 'locked emoji'],
      [D.relay.servers.length, 'relay servers'],
      [(D.bot.actions || []).length, 'bot commands'],
      [(D.sheets || []).length, 'sheet tabs'],
    ];

    const box = document.getElementById('about-stats');
    if (box) {
      box.innerHTML = stats.map(([n, l]) =>
        '<div class="about-stat"><div class="num">' + esc(n) + '</div><div class="lbl">' + esc(l) + '</div></div>'
      ).join('');
    }

    const pill = document.getElementById('about-pillars');
    if (pill) {
      const pillars = [
        ['🗂', 'Your Drive is the database', 'A room is a Google Sheet in the owner\'s Drive. We host the web page and nothing else. If the app vanished tomorrow your messages would still be there.'],
        ['🔗', 'A link is the whole signup', 'No account, no email, no password. Open the link, pick a name, you are in.'],
        ['🔐', 'Encryption you opt into', 'Set a room passphrase and every new message is encrypted on the device before it is sent. The key never leaves.'],
        ['📴', 'Built for weak networks', 'Messages travel peer-to-peer and over a multi-server relay at the same time. If one path is blocked, the other still delivers.'],
        ['🕵️', 'No accounts, no tracking', 'No profile, no analytics, no advertising network. There is nothing to sell because there is no database of you.'],
        ['🎨', 'Yours to shape', 'Wallpapers, a 500-plus emoji set, a room-wide music player, and an assistant that understands room commands.'],
      ];
      pill.innerHTML = pillars.map(([icon, title, body]) =>
        '<div class="about-pillar"><h3><span>' + icon + '</span> ' + esc(title) + '</h3><p>' + esc(body) + '</p></div>'
      ).join('');
    }

    const facts = document.getElementById('about-facts');
    if (facts) {
      const rows = [
        ['Rooms are backed by', 'a Google Sheet with ' + (D.sheets || []).length + ' tabs'],
        ['Custom emoji', D.assets.emoji.total + ' images in ' + D.assets.emoji.categories.length + ' categories'],
        ['Locked emoji pack', D.assets.special.count + ' images, encrypted on disk, unlocked with a password'],
        ['Wallpapers', D.assets.themes + ' of them, shared with the whole room'],
        ['Room radio', D.assets.music + ' tracks, synchronised across devices'],
        ['Cross-device relay', D.relay.servers.length + ' independent servers, all used at once'],
        ['Assistant commands', (D.bot.actions || []).length + ' room commands plus free-form questions'],
        ['Encryption', (D.encryption || {}).cipher + ' with a ' + (D.encryption || {}).kdf + ' key (' + (D.encryption || {}).iterations + ' rounds)'],
        ['Offline cache', (D.storage || {}).indexeddb ? (D.storage.indexeddb.name + ', version ' + D.storage.indexeddb.version) : 'IndexedDB'],
      ];
      facts.innerHTML = rows.map(([k, v]) =>
        '<tr><td>' + esc(k) + '</td><td>' + esc(v) + '</td></tr>'
      ).join('');
    }

    const foot = document.getElementById('about-generated');
    if (foot) {
      foot.textContent = 'Built from the app source on ' + String(D.generatedAt || '').slice(0, 10) + '.';
    }
  }

  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', fill);
  else fill();
})();
